/* Embedded logos (base64) so the site works without an images folder */
const LOGOS = {
  crimson: "data:image/webp;base64,",
  icon: "data:image/webp;base64,",
  full: "data:image/webp;base64,"
};
document.querySelectorAll('img[data-logo]').forEach(function (img) {
  img.src = LOGOS[img.dataset.logo];
});
